import random

def test(n):
 A=[set() for _ in range(n)]
 es=[(i,j) for i in range(n) for j in range(i)]
 random.shuffle(es)
 def reachable(i,j):
  cur={i}
  for l in range(1,5):
   cur=set.union(set(),*(A[x] for x in cur))
   if l in (2,4) and j in cur:return True
  return False
 for i,j in es:
  if not reachable(i,j):A[i].add(j);A[j].add(i)
 d=min(map(len,A))
 gap=min((len(A[i]^A[j]) for i in range(n) for j in range(i) if A[i]!=A[j]),default=n)
 return d,gap,A
best=10
for n in [10,15,20,30,40]:
 for _ in range(100):
  d,g,A=test(n)
  if 5*d>n:
   r=g/(5*d-n)
   if r<best:
    best=r;print(n,d,g,r,flush=True)
print('done')

